// Cheap gate of the conditional target head (CLNA_COND, nnrec.cpp; JOHNDOE #88/#92/#94): invoke the full head with
// probability alpha(g) = sigmoid(kBias + sum_i kW[i] * g_i) over kN inputs that need neither a softmax nor the head:
//   0 native logit margin: max logit of the reference's slots - max logit of the other slots, clipped to [-8, 8], / 8
//   1 round / 2000   2 gems / 100   3 hp / max_hp   4 min(visible enemies, 6) / 6   5 #slots / 11
// This default (all-zero weights, bias = logit(CLNA_EPS)) invokes with probability CLNA_EPS everywhere. A trained gate is
// generated by the learner export with the same layout.
#pragma once
#include <cmath>
namespace clna_cgate {
inline constexpr int kN = 6;
inline constexpr char kVersion[] = "clna-cgate-v1-default";
inline constexpr char kAbi[] = "clna-cgate-abi-v1|margin(clip8)/8,round/2000,gems/100,hp/max_hp,min(enemies,6)/6,slots/11";
inline constexpr float kW[kN] = { 0, 0, 0, 0, 0, 0 };
inline const double kBias = std::log(static_cast<double>(CLNA_EPS) / (1.0 - static_cast<double>(CLNA_EPS)));
}  // namespace clna_cgate
